from builtins import zip


class TxFeature(object):
    def __init__(self):
        self.off = "OFF"

    def compare_tx_power(self, first_tx_power, second_tx_power, tolerance=5):
        """
        Compare output from tx power keywors

        | **Author:** michal.kwasniewicz@nokia.com
        | **Maintainers:** marcin.jezewski@nokia.com, rafal.ozga@nokia.com
        | **Released with version:** x.x.x

        | **Full description:**
        | Compare output from keywords: Get Tx Power, Get Lte Tx Power, Get Gsm Tx Power,
        | Get Wcdma Tx Power with setup tolerance

        **Input Parameters:**

        +-------------------+------+---------------------------------------------------------------------------+
        | Input Parameters  | Man. | Description                                                               |
        +===================+======+===========================================================================+
        | first_tx_power    | Yes  | first tx power dictionary                                                 |
        +-------------------+------+---------------------------------------------------------------------------+
        | second_tx_power   | Yes  | first tx power dictionary                                                 |
        +-------------------+------+---------------------------------------------------------------------------+
        | tolerance         | Yes  | (+/-)tolerance in percent (max difference between tx's) default value 5%  |
        +-------------------+------+---------------------------------------------------------------------------+

        **Example:**

        .. code-block:: robotframework

            ${verdict}=  Compare Tx Power  ${output_get_tx_power_before_reset}  ${output_get_tx_power_after_reset}  7

        | **Return value:**
        | True if all tx are in range, otherwise False.
        """
        for tx_pair in zip(first_tx_power.values(), second_tx_power.values()):
            if not self._compare(tx_pair, tolerance):
                return False
        return True

    def _compare(self, tx_tuple, tolerance):
        if self._is_off(tx_tuple):
            return self._are_all_off(tx_tuple)
        return self._are_in_range(tx_tuple[0], tx_tuple[1], tolerance)

    @staticmethod
    def _are_in_range(reference_power, compared_power, tolerance):
        difference = abs(float(reference_power)) * (float(tolerance) / 100)
        in_max_range = (float(reference_power) + difference) >= float(compared_power)
        in_min_range = (float(reference_power) - difference) <= float(compared_power)
        return in_min_range and in_max_range

    def _is_off(self, tx_tuple):
        return tx_tuple[0] == self.off or tx_tuple[1] == self.off

    def _are_all_off(self, tx_tuple):
        return tx_tuple[0] == self.off and tx_tuple[1] == self.off
